static void weave(int *l, int ln, int *r, int rn, int *prefix, int pn, int **res, int *size, int **cols) {
  if (ln == 0 && rn == 0) {
    res[*size] = (int *)malloc(sizeof(int) * pn);
    for (int i = 0; i < pn; i++) res[*size][i] = prefix[i];
    (*cols)[*size] = pn;
    (*size)++;
    return;
  }
  if (ln > 0) {
    prefix[pn] = l[0];
    weave(l + 1, ln - 1, r, rn, prefix, pn + 1, res, size, cols);
  }
  if (rn > 0) {
    prefix[pn] = r[0];
    weave(l, ln, r + 1, rn - 1, prefix, pn + 1, res, size, cols);
  }
}

static void collect(struct TreeNode *root, int **seqs, int *lens, int *count) {
  if (!root) {
    seqs[*count] = NULL;
    lens[*count] = 0;
    (*count)++;
    return;
  }
  int leftCount = 0, rightCount = 0;
  int **leftSeqs = (int **)malloc(sizeof(int *) * 1000);
  int *leftLens = (int *)malloc(sizeof(int) * 1000);
  int **rightSeqs = (int **)malloc(sizeof(int *) * 1000);
  int *rightLens = (int *)malloc(sizeof(int) * 1000);
  collect(root->left, leftSeqs, leftLens, &leftCount);
  collect(root->right, rightSeqs, rightLens, &rightCount);
  for (int i = 0; i < leftCount; i++) {
    for (int j = 0; j < rightCount; j++) {
      int prefix[1000];
      prefix[0] = root->val;
      weave(leftSeqs[i], leftLens[i], rightSeqs[j], rightLens[j], prefix, 1, seqs, count, &lens);
    }
  }
  free(leftSeqs);
  free(leftLens);
  free(rightSeqs);
  free(rightLens);
}

int **BSTSequences(struct TreeNode *root, int *returnSize, int **returnColumnSizes) {
  int **res = (int **)malloc(sizeof(int *) * 10000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 10000);
  *returnSize = 0;
  collect(root, res, *returnColumnSizes, returnSize);
  return res;
}

class Solution {
  void weave(vector<int> &l, int li, vector<int> &r, int ri, vector<int> &prefix, vector<vector<int>> &res) {
    if (li == (int)l.size() && ri == (int)r.size()) {
      res.push_back(prefix);
      return;
    }
    if (li < (int)l.size()) {
      prefix.push_back(l[li]);
      weave(l, li + 1, r, ri, prefix, res);
      prefix.pop_back();
    }
    if (ri < (int)r.size()) {
      prefix.push_back(r[ri]);
      weave(l, li, r, ri + 1, prefix, res);
      prefix.pop_back();
    }
  }

public:
  vector<vector<int>> BSTSequences(TreeNode *root) {
    if (!root) return {{}};
    vector<vector<int>> left = BSTSequences(root->left);
    vector<vector<int>> right = BSTSequences(root->right);
    vector<vector<int>> res;
    for (auto &l : left) {
      for (auto &r : right) {
        vector<int> prefix = {root->val};
        weave(l, 0, r, 0, prefix, res);
      }
    }
    return res;
  }
};

func BSTSequences(root *TreeNode) [][]int {
	if root == nil {
		return [][]int{{}}
	}
	left := BSTSequences(root.Left)
	right := BSTSequences(root.Right)
	var res [][]int
	var weave func(l, r []int, prefix []int)
	weave = func(l, r []int, prefix []int) {
		if len(l) == 0 && len(r) == 0 {
			tmp := make([]int, len(prefix))
			copy(tmp, prefix)
			res = append(res, tmp)
			return
		}
		if len(l) > 0 {
			weave(l[1:], r, append(prefix, l[0]))
		}
		if len(r) > 0 {
			weave(l, r[1:], append(prefix, r[0]))
		}
	}
	for _, l := range left {
		for _, r := range right {
			weave(l, r, []int{root.Val})
		}
	}
	return res
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private void weave(List<Integer> l, int li, List<Integer> r, int ri, List<Integer> prefix,
      List<List<Integer>> res) {
    if (li == l.size() && ri == r.size()) {
      res.add(new ArrayList<>(prefix));
      return;
    }
    if (li < l.size()) {
      prefix.add(l.get(li));
      weave(l, li + 1, r, ri, prefix, res);
      prefix.remove(prefix.size() - 1);
    }
    if (ri < r.size()) {
      prefix.add(r.get(ri));
      weave(l, li, r, ri + 1, prefix, res);
      prefix.remove(prefix.size() - 1);
    }
  }

  public List<List<Integer>> BSTSequences(TreeNode root) {
    if (root == null) {
      List<List<Integer>> empty = new ArrayList<>();
      empty.add(new ArrayList<>());
      return empty;
    }
    List<List<Integer>> left = BSTSequences(root.left);
    List<List<Integer>> right = BSTSequences(root.right);
    List<List<Integer>> res = new ArrayList<>();
    for (List<Integer> l : left) {
      for (List<Integer> r : right) {
        List<Integer> prefix = new ArrayList<>();
        prefix.add(root.val);
        weave(l, 0, r, 0, prefix, res);
      }
    }
    return res;
  }
}

class Solution:
    def BSTSequences(self, root: Optional[TreeNode]) -> List[List[int]]:
        if root is None:
            return [[]]
        left = self.BSTSequences(root.left)
        right = self.BSTSequences(root.right)
        res = []

        def weave(l, r, prefix):
            if not l and not r:
                res.append(prefix[:])
                return
            if l:
                weave(l[1:], r, prefix + [l[0]])
            if r:
                weave(l, r[1:], prefix + [r[0]])

        for l in left:
            for r in right:
                weave(l, r, [root.val])
        return res

impl Solution {
  pub fn bst_sequences(root: Option<Box<TreeNode>>) -> Vec<Vec<i32>> {
    fn weave(l: &[i32], r: &[i32], prefix: &mut Vec<i32>, res: &mut Vec<Vec<i32>>) {
      if l.is_empty() && r.is_empty() {
        res.push(prefix.clone());
        return;
      }
      if !l.is_empty() {
        prefix.push(l[0]);
        weave(&l[1..], r, prefix, res);
        prefix.pop();
      }
      if !r.is_empty() {
        prefix.push(r[0]);
        weave(l, &r[1..], prefix, res);
        prefix.pop();
      }
    }
    match root {
      None => vec![vec![]],
      Some(node) => {
        let left = Solution::bst_sequences(node.left);
        let right = Solution::bst_sequences(node.right);
        let mut res = vec![];
        for l in &left {
          for r in &right {
            let mut prefix = vec![node.val];
            weave(l, r, &mut prefix, &mut res);
          }
        }
        res
      }
    }
  }
}

const BSTSequences = (root: TreeNode | null): number[][] => {
  if (!root) return [[]];
  const left = BSTSequences(root.left);
  const right = BSTSequences(root.right);
  const res: number[][] = [];

  const weave = (l: number[], r: number[], prefix: number[]) => {
    if (l.length === 0 && r.length === 0) {
      res.push([...prefix]);
      return;
    }
    if (l.length > 0) weave(l.slice(1), r, [...prefix, l[0]]);
    if (r.length > 0) weave(l, r.slice(1), [...prefix, r[0]]);
  };

  for (const l of left) {
    for (const r of right) {
      weave(l, r, [root.val]);
    }
  }
  return res;
};
